8	/// Generate a per-test unit struct implementing [`EnvVar`] from a
9	/// `&[(&str, &str)]` literal — saves each cascade test from spelling
10	/// out an `impl EnvVar` block. Avoids touching the real process
11	/// environment so cascade tests don't need
12	/// [`pacquet_testing_utils::env_guard::EnvGuard`]'s global lock.
13	macro_rules! static_env {
14	    ($name:ident, $entries:expr) => {
15	        struct $name;
16	        impl EnvVar for $name {
17	            fn var(name: &str) -> Option<String> {
18	                let entries: &[(&str, &str)] = $entries;
19	                entries.iter().find(|(k, _)| *k == name).map(|(_, v)| (*v).to_string())
20	            }
21	        }
22	    };
23	}
